import React, { createContext, useState, useContext, useEffect } from 'react';
import axios from 'axios';
import io from 'socket.io-client';
import { useAuth } from './AuthContext';

const ClipboardContext = createContext(null);
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';
const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000';

export const useClipboard = () => useContext(ClipboardContext);

export const ClipboardProvider = ({ children }) => {
  const [clipboards, setClipboards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user } = useAuth();
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    if (user) {
      const newSocket = io(SOCKET_URL, {
        auth: {
          token: localStorage.getItem('token')
        }
      });
      setSocket(newSocket);

      return () => newSocket.close();
    }
  }, [user]);

  useEffect(() => {
    if (socket) {
      socket.on('clipboard-updated', (updatedClipboard) => {
        setClipboards(prevClipboards => {
          const index = prevClipboards.findIndex(c => c._id === updatedClipboard._id);
          if (index !== -1) {
            const newClipboards = [...prevClipboards];
            newClipboards[index] = updatedClipboard;
            return newClipboards;
          }
          return [...prevClipboards, updatedClipboard];
        });
      });
    }
  }, [socket]);

  useEffect(() => {
    if (user) {
      fetchClipboards();
    }
  }, [user]);

  const fetchClipboards = async () => {
    try {
      const response = await axios.get(`${API_URL}/api/clipboard`, {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });
      setClipboards(response.data);
      setError('');
    } catch (err) {
      setError('Failed to fetch clipboards');
    } finally {
      setLoading(false);
    }
  };

  const createClipboard = async (clipboardData) => {
    try {
      const response = await axios.post(
        `${API_URL}/api/clipboard`,
        clipboardData,
        {
          headers: { 'x-auth-token': localStorage.getItem('token') }
        }
      );
      setClipboards([response.data, ...clipboards]);
      socket?.emit('clipboard-update', response.data);
      setError('');
      return response.data;
    } catch (err) {
      setError('Failed to create clipboard');
      throw err;
    }
  };

  const updateClipboard = async (id, clipboardData) => {
    try {
      const response = await axios.put(
        `${API_URL}/api/clipboard/${id}`,
        clipboardData,
        {
          headers: { 'x-auth-token': localStorage.getItem('token') }
        }
      );
      setClipboards(clipboards.map(clipboard => 
        clipboard._id === id ? response.data : clipboard
      ));
      socket?.emit('clipboard-update', response.data);
      setError('');
      return response.data;
    } catch (err) {
      setError('Failed to update clipboard');
      throw err;
    }
  };

  const deleteClipboard = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/clipboard/${id}`, {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });
      setClipboards(clipboards.filter(clipboard => clipboard._id !== id));
      socket?.emit('clipboard-delete', id);
      setError('');
    } catch (err) {
      setError('Failed to delete clipboard');
      throw err;
    }
  };

  const getSharedClipboard = async (link) => {
    try {
      const response = await axios.get(`${API_URL}/api/clipboard/shared/${link}`);
      return response.data;
    } catch (err) {
      setError('Failed to fetch shared clipboard');
      throw err;
    }
  };

  const value = {
    clipboards,
    loading,
    error,
    createClipboard,
    updateClipboard,
    deleteClipboard,
    getSharedClipboard
  };

  return (
    <ClipboardContext.Provider value={value}>
      {children}
    </ClipboardContext.Provider>
  );
};
